package org.walkwithgod.community;import jakarta.persistence.*;import org.walkwithgod.common.BaseEntity;import org.walkwithgod.user.AppUser;
@Entity @Table(name="comments",indexes=@Index(name="idx_comments_post_created",columnList="post_id,created_at"))public class Comment extends BaseEntity{@ManyToOne(optional=false,fetch=FetchType.LAZY)private Post post;@ManyToOne(optional=false,fetch=FetchType.LAZY)private AppUser author;@Column(nullable=false,length=2000)private String content;public Post getPost(){return post;}public void setPost(Post v){post=v;}public AppUser getAuthor(){return author;}public void setAuthor(AppUser v){author=v;}public String getContent(){return content;}public void setContent(String v){content=v;}}
